import { cacheTag, cacheLife } from 'next/cache'
import { getAllProducts } from '@/lib/db'

export async function getCachedProducts() {
  'use cache'
  cacheTag('products')
  cacheLife('hours')

  const products = await getAllProducts()
  return {
    products,
    syncedAt: new Date().toISOString(),
  }
}

import { cacheTag, cacheLife } from 'next/cache'
import { getAllProducts } from '@/lib/db'

export async function getCachedProducts() {
  'use cache'
  cacheTag('products')
  cacheLife('hours')

  const products = await getAllProducts()
  return {
    products,
    syncedAt: new Date().toISOString(),
  }
}

